/**
 * Minimal analytics service.
 *
 * In a real app this would POST to an external analytics endpoint
 * (e.g. PostHog, Vercel Analytics, a custom ingestion API). It is kept
 * dependency-free here so it works in any runtime.
 */

export type PageViewEvent = {
  path: string
  userAgent: string
  /** ISO timestamp captured at request time */
  timestamp: string
}

export async function logPageView(event: PageViewEvent): Promise<void> {
  // Simulate a fire-and-forget network call to an analytics backend.
  // In production replace this with a real fetch() to your provider.
  await new Promise((resolve) => setTimeout(resolve, 50))
  console.info('[analytics] page view:', event)
}

