import { after } from 'next/server'
import { headers } from 'next/headers'
import { logPageView } from '@/lib/analytics'

export default async function Home() {
  // Read request-time data BEFORE scheduling `after`. In a Server Component
  // you cannot call `headers()`/`cookies()` inside the `after` callback
  // (it runs after React's render lifecycle), so we capture it here and pass
  // the values in via closure.
  const headersList = await headers()
  const userAgent = headersList.get('user-agent') || 'unknown'
  const timestamp = new Date().toISOString()

  // Schedule the analytics write to run after the response is sent, so it
  // does not block the user from receiving the page. `after` is Next.js's
  // recommended primitive for post-response work.
  after(() => {
    void logPageView({
      path: '/',
      userAgent,
      timestamp,
    })
  })

  return (
    <main>
      <h1>Welcome</h1>
      <p>Thanks for stopping by — your visit has been noted.</p>
    </main>
  )
}

